#ifndef CACHE_ENTRY_h
#define CACHE_ENTRY_h

#include "transaction.h"

#include <cstdint>

////////////////////////////////////////////////////////////////////////////
////////////////////////////////////////////////////////////////////////////

extern uint64_t GL_CYCLE;

////////////////////////////////////////////////////////////////////////////
////////////////////////////////////////////////////////////////////////////

constexpr int8_t RRIP_MAX = 7;

////////////////////////////////////////////////////////////////////////////
////////////////////////////////////////////////////////////////////////////

struct CacheEntry
{
    bool valid =false;
    bool dirty =false;
    uint64_t address;
    /*
     * Replacement policy data:
     * */
    uint64_t timestamp;
    int8_t  rrpv;

    bool reused_after_marked_dirty =false;
    bool likely_dead =false;
    bool new_install =false;

    CacheEntry(void) =default;
};

////////////////////////////////////////////////////////////////////////////
////////////////////////////////////////////////////////////////////////////

struct MSHREntry
{
    bool is_fired =false;
    bool is_for_write_allocate;
    Transaction trans;

    uint64_t cycle_fired;

    MSHREntry(Transaction t, bool is_write=false)
        :is_for_write_allocate(is_write),
        trans(t),
        cycle_fired(GL_CYCLE)
    {}
};

////////////////////////////////////////////////////////////////////////////
////////////////////////////////////////////////////////////////////////////
/*
 * Cache set declaration:
 * */
using cset_type =       std::vector<CacheEntry>;
using cset_array =      std::vector<cset_type>;

template <class ITER>
ITER cset_find(uint64_t address, ITER begin, ITER end);

template <class ITER>
size_t cset_get_lru_position_of_entry(const CacheEntry&, ITER begin, ITER end);

template <class ITER>
ITER cset_get_way_in_lru_position(ITER begin, ITER end, size_t position);

////////////////////////////////////////////////////////////////////////////
////////////////////////////////////////////////////////////////////////////

#include "entry.tpp"

////////////////////////////////////////////////////////////////////////////
////////////////////////////////////////////////////////////////////////////

#endif  // CACHE_ENTRY_h
